<script>
 import RegionState from './RegionState.svelte';
 import {onMount,tick} from 'svelte';
 import {FolderOpen,ImagePlus,Play,Download,Square,FileJson,ArrowLeftRight,Info,Check} from 'lucide-svelte';
 import {createNewProductStore} from '../stores/new-product.svelte';
 import {droppedProductFiles} from '../services/new-product-files.ts';
 import {assignmentOrder,assignmentColors,shotLabels} from '../lib/new-product.ts';
 import {ratios,chooseRatio,swapRatio,ratioLabel} from '../lib/ratio.ts';
 import {shortcutScope} from '../lib/shortcuts.ts';
 import Button from '../ui/Button.svelte';import Segmented from '../ui/Segmented.svelte';import Spinner from '../ui/Spinner.svelte';
 let {active=true}=$props();
 const np=createNewProductStore(),s=np.state;
 let picker,hot=$state(false),key=$state(''),keyBusy=$state(false);
 const busy=$derived(['importing','analyzing','starting','running','awaiting_confirm'].includes(s.phase));
 const job=$derived(s.jobs.find(job=>job.id===s.activeJobId));
 const showingJob=$derived(!!job&&['running','waiting','done','partial','failed','cancelled','attention','cancelling'].includes(s.phase));
 const tasks=$derived(showingJob?job.tasks:s.manifest?.tasks||job?.tasks||[]);
 const questions=$derived(s.manifest?.pending||[]);
 const completed=$derived(job?.tasks.filter(task=>task.state==='done')||[]);
 const labels={idle:'准备素材',importing:'正在导入并精确去重',analyzing:'Gemini 正在识别图片',needs_input:'需要你补充',ready:'任务单已就绪',awaiting_confirm:'等待继续',starting:'正在建立任务',running:'正在生成套图',waiting:'等待异步结果',done:'套图已完成',partial:'部分完成',failed:'需要检查',attention:'部分请求结果待确认',cancelled:'已停止',queued:'排队中',submitted:'已提交',submitting:'正在提交',uncertain:'结果待确认',blocked:'依赖任务未完成',cancelling:'正在停止后续提交'};
 const appearanceTargets=[['outer_shell','外壳'],['cap','盖子'],['refill','纸浆内托'],['graphics','图案'],['brand_text','品牌文字']];
 onMount(()=>{void np.begin();return np.dispose;});
 $effect(()=>{const phase=s.phase;if(phase==='needs_input'||phase==='awaiting_confirm')void tick().then(()=>{if(s.phase!==phase)return;const region=document.querySelector(phase==='needs_input'?'.np-questions':'.np-confirm-row');region?.scrollIntoView({block:'center',behavior:'instant'});region?.querySelector('select,button')?.focus({preventScroll:true});});});
 function kinds(id){return s.assignmentMode==='manual'?(s.assignments[id]||[]):[...new Set((s.manifest?.tasks||[]).filter(task=>task.referenceIds[0]===id).map(task=>task.kind))];}
 function name(id){const asset=s.assets.find(asset=>asset.id===id);if(asset)return asset.name;const index=job?.context?.resolvedTarget?.ids?.indexOf(id);return index>=0?job.context.fileNames[index]:id;}
 function imageInfo(id){return s.analysis?.items.find(item=>item.assetId===id);}
 async function dropped(event){event.preventDefault();event.stopPropagation();hot=false;if(busy)return;try{await np.importFiles(await droppedProductFiles(event.dataTransfer),'拖入素材');}catch(error){s.error=error.message;}}
 function changeCount(kind,value){s.options[kind]=Math.max(0,Math.min(8,Number(value)||0));np.rebuild();}
 function changeAppearance(target){const old=s.options.appearance.targets;s.options.appearance.targets=old.includes(target)?old.filter(value=>value!==target):[...old,target];np.rebuild();}
 async function saveKey(){keyBusy=true;try{await np.saveKey(key);key='';}catch(error){s.error=error.message;}finally{keyBusy=false;}}
</script>
<section class="np-page" use:shortcutScope={{name:'new-product',exclusive:false,bindings:active&&s.confirmation?[{key:'Escape',action:()=>np.cancelConfirmation()}]:active&&s.phase==='running'?[{key:'Escape',action:()=>np.cancel()}]:[]}}>
   <div class="np-start"><Button variant="primary" busy={['importing','analyzing','starting'].includes(s.phase)} disabled={busy||!s.assets.length||!s.capabilities?.configured} onclick={()=>np.oneClick(true)}><Play size={15}/>{s.analysis?(showingJob&&!busy?'重新生成整套':'确认任务单并生成'):'识别并生成套图'}</Button><Button disabled={busy||!s.assets.length||!s.capabilities?.configured} onclick={()=>np.oneClick(false)}>仅识别并制作任务单</Button><p class="np-phase" aria-live="polite">{labels[s.phase]||s.phase}</p><small>识别和生成可能产生费用，超过数量或费用门槛时会先确认。</small></div>
 <div class="np-heading"><div><h1>新品套图</h1><p>一组原图，整理成一套一致的产品摄影。</p></div><span class="np-models">Gemini 3.8 Flash <span>→</span> Nano Banana 2.1</span></div>
 {#if ['idle','loading'].includes(s.capabilityState)}<RegionState compact title="正在读取新品配置"/>{:else if s.capabilityState==='error'}<RegionState compact state="error" title="无法读取新品配置" message={s.capabilityError} onretry={np.reloadCapabilities}/>{/if}
 {#if s.capabilities?.mock}<div class="np-notice">当前为交互演示，不会调用AI或返回假成图。</div>{/if}
 {#if s.error}<div class="np-error" role="alert">{s.error}</div>{/if}
 <div class="np-layout">
  <div class="np-content">
   <section class:hot class="np-input" aria-label="新品原图" ondragover={event=>{event.preventDefault();event.stopPropagation();if(!busy)hot=true;}} ondragleave={()=>hot=false} ondrop={dropped}>
    <div class="np-section-title"><h2>原始素材 <span>{s.assets.length?s.assets.length+' 张':''}</span></h2><div class="np-actions"><Button disabled={busy} onclick={()=>np.chooseSource()}><FolderOpen size={15}/>选择素材文件夹</Button><Button disabled={busy} onclick={()=>picker.click()}><ImagePlus size={15}/>添加图片</Button></div></div>
    <input bind:this={picker} class="ui-sr-only" tabindex="-1" type="file" multiple accept="image/png,image/jpeg,image/webp" aria-label="添加新品原图" onchange={event=>{const files=[...event.currentTarget.files];void np.importFiles(files,'图片套图');event.currentTarget.value='';}}/>
    {#if !s.assets.length}<div class="np-drop"><ImagePlus size={30}/><strong>把产品原图拖到这里</strong><p>正面、侧面、开盖、手持和部件图都可以。不要用素材总览截图代替原图。</p><small>PNG / JPG / WebP · 最多 40 张不同原图</small></div>
    {:else}
     <div class="np-assignment-head"><Segmented label="用途分配" options={[{value:'auto',label:'自动分配'},{value:'manual',label:'手动指定'}]} value={s.assignmentMode} disabled={busy} onchange={value=>{if(value==='manual')np.enableManual();else s.assignmentMode='auto';np.rebuild();}}/><span>{s.assignmentMode==='manual'?'先选用途，再点图片；可以一图多选。':'识别后自动分配；也可以直接点选用途。'}</span></div>
     <div class="np-kind-tools" role="group" aria-label="选择生成用途">{#each assignmentOrder as kind}<button type="button" class:active={s.activeKind===kind} style:--kind-color={assignmentColors[kind]} disabled={busy} aria-pressed={s.activeKind===kind} onclick={()=>s.activeKind=kind}><i></i>{shotLabels[kind]}</button>{/each}</div>
     <div class="np-source-grid">{#each s.assets as asset (asset.id)}{@const selected=kinds(asset.id)}{@const info=imageInfo(asset.id)}
      <button type="button" class="np-source" disabled={busy} aria-pressed={selected.includes(s.activeKind)} aria-label={`${asset.name}，用途：${selected.map(kind=>shotLabels[kind]).join('、')||'尚未指定'}`} onclick={()=>np.toggleAssignment(asset.id)} title={`${asset.name} · 点击切换${shotLabels[s.activeKind]}`}>
       <div class="np-thumb"><img src={asset.previewUrl} alt={asset.name}/>{#each assignmentOrder as kind,index}{#if selected.includes(kind)}<span class="np-ring" data-kind={kind} style:--inset={`${12-index*4}px`} style:border-color={assignmentColors[kind]}></span>{/if}{/each}</div>
       <b>{asset.name}</b><span class="np-source-tags">{#if selected.length}{#each assignmentOrder.filter(kind=>selected.includes(kind)) as kind}<span style:color={assignmentColors[kind]}>{shotLabels[kind]}</span>{/each}{:else}<span>{info?.view||'待识别'}</span>{/if}</span>
       {#if s.manifest?.tasks.some(task=>task.anchor&&task.referenceIds[0]===asset.id)}<small>改款基准参考</small>{/if}{#if asset.aliases?.length}<small>已合并 {asset.aliases.length} 个完全相同文件</small>{:else if info?.duplicateOf}<small>{info.duplicateConfidence>=.95?'相似图候选':'相似待判断'} · {name(info.duplicateOf)}</small>{/if}
      </button>
     {/each}</div>
     <p class="np-hint">方框从内到外：白底 → 场景 → 真人 → 爆炸图。方框代表以该图为主图的生成用途，辅助参考图不计入方框。</p>
    {/if}
   </section>
   <section class="np-brief"><h2>你的要求</h2><textarea aria-label="新品套图要求" maxlength="2000" rows="3" value={s.brief} disabled={busy} placeholder="例如：奶油白外壳，保持纸浆内托原色；北欧静物，欧美成年模特手持，画面干净高级。" oninput={event=>{s.brief=event.currentTarget.value;np.resetAnalysis();}}></textarea>
    <details><summary>已知产品结构与材质</summary><textarea aria-label="已知产品事实" rows="3" maxlength="1800" value={s.facts} disabled={busy} oninput={event=>{s.facts=event.currentTarget.value;np.resetAnalysis();}}></textarea><p class="np-hint">这是你确认的事实，优先于模型对照片材质的猜测。</p></details>
   </section>
   {#if questions.length}<section class="np-questions" aria-label="识别后需要补充" aria-live="polite"><h2>有几处需要你确认</h2><p>先问清楚，再生成；相同产品的问题只问一次。</p>
    {#each questions as question}<div class="np-question"><label for={`answer-${question.id}`}>{question.question}</label><select id={`answer-${question.id}`} value={s.answers[question.id]?.choice||''} onchange={event=>np.setAnswer(question.id,event.currentTarget.value)}><option value="">请选择</option>{#each question.options as option}<option value={option.id}>{option.label}</option>{/each}</select><input aria-label={`${question.question} 补充说明`} value={s.answers[question.id]?.text||''} placeholder="可补充颜色、露出高度、装配关系或要保留的部分" oninput={event=>np.setAnswer(question.id,s.answers[question.id]?.choice||'custom',event.currentTarget.value)}/>{#if question.kind==='exploded'&&s.answers[question.id]?.choice==='visible'}<label class="np-question-refs">爆炸图参考图<select multiple size="4" aria-label="爆炸图澄清参考图" onchange={event=>np.setQuestionReferences(question.productId,[...event.currentTarget.selectedOptions].map(option=>option.value))}>{#each s.assets.filter(asset=>s.analysis.items.some(item=>item.assetId===asset.id&&item.productId===question.productId)) as asset}<option value={asset.id} selected={s.manualRefs[question.productId+':exploded']?.includes(asset.id)}>{asset.name}</option>{/each}</select></label>{/if}</div>{/each}
    <Button variant="primary" onclick={()=>np.continueQuestions(true)}>确认答案并生成</Button>
   </section>{/if}
   {#if s.confirmation}<div class="np-confirm-row" role="status"><span>{s.confirmation.message}</span><Button variant="primary" onclick={()=>np.confirm()}>{s.confirmation.stage==='analysis'?'确认并开始识别':'确认费用并开始生成'}</Button><Button onclick={()=>np.cancelConfirmation()}>取消</Button></div>{/if}
   {#if tasks.length}<section class="np-manifest"><div class="np-section-title"><h2>{showingJob?'本批任务':'生成任务单'} <span>{tasks.filter(task=>task.enabled).length} 张</span></h2>{#if showingJob&&!busy&&s.manifest}<Button onclick={()=>np.touchManifest()}>调整下一批任务</Button>{/if}<Button variant="subtle" onclick={()=>np.exportManifest()} disabled={!s.manifest}><FileJson size={15}/>导出任务单</Button></div>
    <div class="np-task-list">{#each tasks as task (task.id)}<div class="np-task"><div class="np-task-main"><input type="checkbox" aria-label={`生成 ${task.title}`} checked={task.enabled} disabled={busy||showingJob||!s.manifest||task.anchor} onchange={event=>{task.enabled=event.currentTarget.checked;np.touchManifest();}}/><span class="np-task-kind" style:--kind-color={assignmentColors[task.kind]}>{shotLabels[task.kind]}</span><strong>{task.title}</strong><span class="np-task-status">{task.state?labels[task.state]||task.state:task.anchor?'统一设计锚点':task.dependsOn.length?'等待定稿后生成':'可并行'}</span></div>
     <div class="np-task-refs">参考：{task.referenceIds.map(name).join(' · ')}{#if task.dependsOn.length}<span> + 同一设计定稿</span>{/if}</div>
     {#if task.error}<p class="np-error">{task.error}</p>{/if}
     <details><summary>提示词与参考图</summary><textarea aria-label={`${task.title} 提示词`} rows="7" value={task.prompt} disabled={busy||showingJob||!s.manifest} oninput={event=>{task.prompt=event.currentTarget.value;np.touchManifest();}}></textarea>
      {#if !showingJob&&s.manifest&&s.analysis}<label>手动调整参考图（更换后更新自动提示词）<select multiple size="4" aria-label={`${task.title} 参考图`} disabled={busy} onchange={event=>np.setTaskReferences(task,[...event.currentTarget.selectedOptions].map(option=>option.value))}>{#each s.assets.filter(asset=>s.analysis.items.some(item=>item.assetId===asset.id&&item.productId===task.productId)) as asset}<option value={asset.id} selected={task.referenceIds.includes(asset.id)}>{asset.name}</option>{/each}</select></label>{/if}
     </details>
    </div>{/each}</div>
   </section>{/if}
   {#if job}<section class="np-results"><div class="np-section-title"><h2>本批结果 <span>{completed.length} / {job.tasks.length}</span></h2><div class="np-actions"><span>{labels[job.status]||job.status}</span><Button disabled={!completed.length} onclick={()=>np.downloadAll()}><Download size={15}/>下载整套 ZIP</Button>{#if !['done','partial','failed','attention','cancelled'].includes(job.status)}<Button disabled={s.stopRequested} onclick={()=>np.cancel()}><Square size={13}/>停止后续提交</Button>{/if}</div></div>
    {#if s.stopRequested}<p class="np-hint">已停止新增提交；已经提交的请求仍可能返回，完成结果会保留。</p>{/if}
    {#if s.savingError}<p class="np-error" role="alert">{s.savingError} <button type="button" onclick={()=>np.chooseOutput()}>重新选择保存目录</button></p>{/if}
    <div class="np-result-grid">{#each completed as task}{@const output=s.outputs[`${job.id}:${task.id}`]}<figure>{#if output}<a href={output.url} target="_blank" rel="noreferrer" title="打开原尺寸"><img src={output.url} alt={task.title}/></a>{:else}<div class="np-result-loading"><Spinner/>正在读取图片</div>{/if}<figcaption><b>{task.title}</b><span>{output?.saved?'已校验保存到文件夹':'已保存在工作区'}</span></figcaption></figure>{/each}</div>
   </section>{/if}
  </div>
  <aside class="np-controls" aria-label="套图设置"><h2>套图设置</h2>
   <div class="np-setting"><span class="np-field-title">输出比例</span><div class="np-ratios">{#each ratios as ratio}<button type="button" disabled={busy} class:chosen={s.options.ratio.ratio===ratio} aria-pressed={s.options.ratio.ratio===ratio} onclick={()=>{s.options.ratio=chooseRatio(ratio);np.rebuild();}}>{s.options.ratio.ratio===ratio?ratioLabel(s.options.ratio):ratio}</button>{/each}<button type="button" aria-label="交换比例方向" disabled={busy||s.options.ratio.ratio==='1:1'} onclick={()=>{s.options.ratio=swapRatio(s.options.ratio);np.rebuild();}}><ArrowLeftRight size={15}/></button></div></div>
   <div class="np-setting"><span class="np-field-title">分辨率</span><Segmented label="输出分辨率" options={['1K','2K','4K'].map(value=>({value,label:value}))} value={s.options.resolution} disabled={busy} onchange={value=>{s.options.resolution=value;np.rebuild();}}/></div>
   <div class="np-setting"><span class="np-field-title">处理模式</span><Segmented label="处理模式" options={[{value:'realtime',label:'实时生成'},{value:'batch',label:'异步批量'}]} value={s.options.mode} disabled={busy} onchange={value=>{s.options.mode=value;np.rebuild();}}/><p>{s.options.mode==='batch'?'异步批量通常更省费用，但等待更久；改款可能分两阶段提交。':'直接并行请求，逐张返回结果。'}</p></div>
   <label class="np-setting">实时并发<select aria-label="实时并发数" value={s.options.concurrency} disabled={busy||s.options.mode==='batch'} onchange={event=>{s.options.concurrency=Number(event.currentTarget.value);np.rebuild();}}>{#each [1,2,3,4] as value}<option value={value}>{value} 张同时生成</option>{/each}</select></label>
   <div class="np-setting np-counts"><span class="np-field-title">{s.assignmentMode==='manual'?'每张已选素材的输出张数':'自动任务数量'}</span>{#if s.assignmentMode==='auto'}<label class="np-check"><input type="checkbox" checked={s.options.white} disabled={busy} onchange={event=>{s.options.white=event.currentTarget.checked;np.rebuild();}}/>每个有效角度 1 张白底</label>{/if}
    {#each ['scene','human','exploded'] as kind}<label>{shotLabels[kind]}<input type="number" min={s.assignmentMode==='manual'?1:0} max="8" aria-label={`${shotLabels[kind]}数量`} value={s.assignmentMode==='manual'?s.options.copies[kind]:s.options[kind]} disabled={busy} onchange={event=>{if(s.assignmentMode==='manual'){s.options.copies[kind]=Math.max(1,Math.min(8,Number(event.currentTarget.value)||1));np.rebuild();}else changeCount(kind,event.currentTarget.value);}}/></label>{/each}
   </div>
   <div class="np-setting"><span class="np-field-title">产品外观</span><Segmented label="产品外观" options={[{value:'preserve',label:'保持原样'},{value:'customize',label:'定向改款'}]} value={s.options.appearance.mode} disabled={busy} onchange={value=>{s.options.appearance.mode=value;np.rebuild();}}/>
    {#if s.options.appearance.mode==='customize'}<div class="np-targets">{#each appearanceTargets as [value,label]}<label><input type="checkbox" checked={s.options.appearance.targets.includes(value)} disabled={busy} onchange={()=>changeAppearance(value)}/>{label}</label>{/each}</div><textarea aria-label="外观改款要求" rows="3" value={s.options.appearance.instruction} disabled={busy} placeholder="例如：只把外壳改成哑光雾蓝，盖子保持白色；纸浆材质和旋转结构不变。" oninput={event=>{s.options.appearance.instruction=event.currentTarget.value;np.rebuild();}}></textarea><p>先生成一张白底设计定稿，再统一其余图片的外观，计入输出数量。</p>{:else}<p>保留颜色、材质、外形、文字和机构，不把“高级”理解成重新设计。</p>{/if}
   </div>
   <label class="np-setting">空托 / 内容物<select aria-label="内容物处理" value={s.options.contents} disabled={busy} onchange={event=>{s.options.contents=event.currentTarget.value;np.rebuild();}}><option value="ask">不确定时先问我</option><option value="add">我已确认：需要加入膏体</option><option value="empty">我已确认：保持空托</option></select></label>
   <div class="np-setting"><span class="np-field-title">结果保存</span><Button disabled={['importing','starting'].includes(s.phase)} onclick={()=>np.chooseOutput()}><FolderOpen size={15}/>{s.outputName?'更换保存目录':'选择保存目录'}</Button><p>{s.outputName?`${s.outputName} / 新品套图 / 本批目录`:'未选目录时，结果保存在工作区，可一次下载ZIP。'}</p></div>


 {#if s.capabilities?.mock}<p class="np-notice">模拟模式支持导入与用途选择；图像识别和套图生成未启用。</p>{:else if s.capabilityState==='ready'&&!s.capabilities?.configured}<details class="np-key" open><summary>Google API 连接</summary>{#if window.__gvpakLocalHost}<label>API 密钥<input type="password" aria-label="Google API密钥" autocomplete="off" bind:value={key}/></label><Button disabled={!key.trim()} busy={keyBusy} onclick={saveKey}>保存到主机</Button>{:else}<p>请联系主机管理员配置 Google API。</p>{/if}</details>{/if}
   {#if s.jobs.length}<label class="np-setting">最近新品任务<select aria-label="最近新品任务" value={s.activeJobId||''} onchange={event=>{s.activeJobId=event.currentTarget.value;s.manifest=null;s.phase='running';s.stopRequested=false;void np.refreshJobs();}}>{#each s.jobs as item}<option value={item.id}>{new Date(item.createdAt*1000).toLocaleString()} · {labels[item.status]||item.status}</option>{/each}</select></label>{/if}
  </aside>
 </div>
</section>

<style>
 .np-page{max-width:1760px;margin:0 auto;padding:24px 32px 48px;color:var(--text)}.np-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:24px}.np-heading h1{font-size:20px;line-height:1.4;margin:0 0 8px;font-weight:600}.np-heading p{margin:0;color:var(--text-dim);font-size:13px}.np-models{font-size:12px;color:var(--text-dim);white-space:nowrap}.np-models span{padding:0 8px}.np-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;align-items:start}.np-content{min-width:0}.np-section-title{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.np-page h2{font-size:14px;font-weight:600;margin:0}.np-page h2 span{font-size:12px;color:var(--text-dim);font-weight:400;margin-left:8px}.np-actions{display:flex;gap:8px;align-items:center;font-size:12px}.np-input,.np-brief,.np-manifest,.np-results{margin-bottom:24px}.np-input{border:1px solid var(--border);border-radius:8px;padding:16px;background:var(--bg-elev)}.np-input.hot{border-color:var(--accent);background:var(--accent-soft)}.np-drop{min-height:252px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:var(--text-dim);text-align:center;padding:24px}.np-drop strong{font-size:14px;color:var(--text)}.np-drop p{font-size:13px;line-height:1.8;max-width:52ch;margin:0}.np-drop small{font-size:12px}.np-assignment-head{display:flex;align-items:center;gap:16px;margin:16px 0}.np-assignment-head>span{font-size:12px;color:var(--text-dim)}.np-kind-tools{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.np-kind-tools button{display:inline-flex;align-items:center;gap:6px;min-height:30px;border:1px solid var(--border);border-radius:6px;padding:4px 10px;background:var(--bg-elev);font-size:12px;color:var(--text)}.np-kind-tools i{width:10px;height:10px;border:2px solid var(--kind-color)}.np-kind-tools button.active{border-color:var(--kind-color);background:color-mix(in srgb,var(--kind-color) 12%,var(--